(148,'_site_transient_feed_6f409681938158427d2ded6eb1b9ea27','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:5:\"\n\n	\n	\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:141:\"\n\n		\n		\n		\n				\n		\n		\n\n		\n		\n					\n				\n\n			\n				\n\n			\n				\n\n			\n				\n\n			\n				\n\n			\n				\n\n			\n				\n\n			\n				\n\n			\n				\n\n			\n				\n\n					\n		\n	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"WordPress | サポートフォーラム » 返信一覧\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"https://ja.wordpress.org/support/forums/feed\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:13:\"lastBuildDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 28 Aug 2026 05:51:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:9:\"generator\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"https://bbpress.org/?v=2.7.0-alpha-2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"ja\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694497\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"返信先: サブドメイン設定後のアクセス可否について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694497\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 28 Aug 2026 01:45:49 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2562:\"\n						\n						<p class=\"wp-block-paragraph\">お二方からの丁寧な回答、ありがとうございます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">質問時までてっきり、サブドメイン（https://sub-hogehoge.abc.or.jp/）を割り当ててアドレスを書き換えれば、既存サイト（https://hogehoge.xsrv.jp/）のコンテンツがそのまま活きるのかと思っておりました。エックスサーバー内の移行が必要になるとのご指摘、たいへん助かりました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">ということは、そもそも新規サイト作成時も、WordPressのインストール前に、ドメイン・サブドメインの割り当てを行うべき（さもないと移行の手間が発生する）なのですね。</p>\n\n\n\n<p class=\"wp-block-paragraph\">ご回答を受けて、既存サイトをxsrv.jpのまま公開するか否かは、関係者にもう少し相談してみます。現在はアクセス制限をかけています。</p>\n\n\n\n<p class=\"wp-block-paragraph\">ちなみに abc.or.jp（仮名）はエックスサーバーではない他社です。サーバー管理者が「サブドメインの割り当て」経験があるのか、現時点では不明なため、少し躊躇がありました。こちらも相談してみます。</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>今回の学び</strong></p>\n\n\n\n<ul>\n<li>エックスサーバーでは、ファイル（WordPressなど）を既に設置したサイトに、後から別ドメイン・サブドメインを割り当てると、ファイルの移行が必要となる。ファイルがWordPressとそのコンテンツである場合は、エックスサーバーの「WordPress 簡単移行」機能が使える。</li>\n\n\n\n<li>既存のサイトを公開していた場合は、同じレンタルサーバー内の移行であっても、移行後にリダイレクトの設定が必要である（設定しないとリダイレクトされない）。</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">本当にどうもありがとうございました。</p>\n\n\n<ul id=\"bbp-reply-revision-log-11694497\" class=\"bbp-reply-revision-log\">\n\n	<li id=\"bbp-reply-revision-log-11694497-item-11694498\" class=\"bbp-reply-revision-log-item\">\n		この返信は3時間、 57分前に<a href=\"https://ja.wordpress.org/support/users/masako2026/\" title=\"masako2026 のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">masako2026</span></a>が編集しました。\n	</li>\n\n</ul>\n\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"masako2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694496\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"返信先: サブドメイン設定後のアクセス可否について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694496\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 27 Aug 2026 09:42:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4683:\"\n						\n						<p class=\"wp-block-paragraph\">少し補足しておきます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">エックスサーバーはドメインごとに設置場所が分かれます。<br />レンタルサーバーによっては、初期ドメインで使っているディレクトリに後から別のドメインを割り当てられるものもありますが、エックスサーバーはそうではありません。</p>\n\n\n\n<p class=\"wp-block-paragraph\">エックスサーバーではドメインごとにドキュメントルート（ファイルの設置場所）が割り当てられるため、初期ドメイン（hogehoge.xsrv.jp）と、後から追加する独自ドメイン（abc.or.jp およびそのサブドメイン）とでは、ファイルの設置場所が別々になります。</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>アドレスを書き換えるだけではエラーになります</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">上記のとおり設置場所が別ですので、WordPress 本体のファイルを初期ドメイン側に置いたまま「WordPress アドレス」と「サイトアドレス」だけを書き換えると、以下のような状態になります。</p>\n\n\n\n<ul>\n<li>ログイン後の遷移先が新 URL 側（WordPress が存在しないディレクトリ）になるため、管理画面に入れなくなる</li>\n\n\n\n<li>Cookie の対象ドメインもサイトアドレス基準で判定されるため、旧 URL 側からのログインも正常に行えなくなる</li>\n\n\n\n<li>サイト内のリンクや画像のパスも新 URL 基準で出力されるため、旧 URL 側は正常に表示されなくなる</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">つまり、<strong>旧 URL が 404 になるかどうか以前に、サイト自体が管理・閲覧できない状態になってしまいます。</strong><br />これは将来的に独自ドメインを取得されて切り替える場合でも同じです。</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>初期ドメインで本当に「公開」する必要があるかご検討ください</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">後からドメインを変更されることが見込まれている場合、初期ドメインでは公開せず、アクセス制限（Basic 認証等）をかけて関係者のみが確認できる状態にしておく方法もあります。</p>\n\n\n\n<p class=\"wp-block-paragraph\">こうしておけば、ドメインが決まった時点で移行するだけで済み、リダイレクトの設定も不要になります。<br />逆に一度公開してしまうと、検索エンジンに初期ドメインの URL が登録されたり、外部からリンクされたりするため、移行後も長期間リダイレクトを維持する必要が出てきます。</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>実際の移行方法</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">エックスサーバーにはサーバーパネルから操作できる「WordPress 簡単移行」という機能があります。他社サーバーからの移行だけでなく、同じサーバー内の別ドメイン（サブドメイン）への移行にも利用できます。ファイルとデータベースの移行、および URL の置換まで自動で行われるため、手作業で移転するより安全です。</p>\n\n\n\n<p class=\"wp-block-paragraph\">利用する際の流れは以下のとおりです。</p>\n\n\n\n<ol>\n<li>サーバーパネルで移行先のサブドメインを作成し、SSL を設定して表示できる状態にする</li>\n\n\n\n<li>移行元の WordPress で、キャッシュ系・セキュリティ系のプラグインを停止しておく</li>\n\n\n\n<li>サーバーパネルの「WordPress 簡単移行」で、移行元 URL と管理者のログイン情報を入力して実行する</li>\n\n\n\n<li>移行後、新 URL で表示・管理画面を確認し、停止したプラグインを有効化する</li>\n\n\n\n<li>（既に公開していた場合）旧 URL 側に、新 URL への 301 リダイレクトを設定する</li>\n</ol>\n\n\n\n<p class=\"wp-block-paragraph\">なお、ドメインやサブドメインの追加後は反映に時間がかかる場合があります。また、移行先にすでに WordPress 等が設置されているとエラーになるため、サブドメインは作成したばかりの空の状態で実行してください。</p>\n\n\n\n<p class=\"wp-block-paragraph\">5 のリダイレクトは .htaccess で設定する方法のほか、サーバーパネルの転送設定機能を利用する方法もあります。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"まーちゅう\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694495\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"返信先: サブドメイン設定後のアクセス可否について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694495\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 27 Aug 2026 05:33:27 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:862:\"\n						\n						<p class=\"wp-block-paragraph\">旧URL が 404 になるかどうかは、旧サイトを残すか、公開を終了するか、転送を設定するかによって変わります。</p>\n\n\n\n<p class=\"wp-block-paragraph\">「WordPress アドレス」と「サイトアドレス」を変更しただけで、旧URL が 404 になったり、新URL への転送が設定されたりするわけではありません。</p>\n\n\n\n<p class=\"wp-block-paragraph\">どうしても初期ドメイン上に作った WordPress を先に公開する必要がある場合、後に新しいサブドメインで公開する際は、「WordPress アドレス」と「サイトアドレス」を書き換えるのではなく、WordPress を新しいサブドメインへ移転し、旧URL から新URL への転送を設定する必要があります。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"瀬戸内ことり (Setouchi Kotori)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694494\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"サブドメイン設定後のアクセス可否について\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:234:\"https://ja.wordpress.org/support/topic/%e3%82%b5%e3%83%96%e3%83%89%e3%83%a1%e3%82%a4%e3%83%b3%e8%a8%ad%e5%ae%9a%e5%be%8c%e3%81%ae%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e5%8f%af%e5%90%a6%e3%81%ab%e3%81%a4%e3%81%84%e3%81%a6/#post-11694494\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 27 Aug 2026 00:55:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1090:\"\n						\n						<p class=\"wp-block-paragraph\">独自ドメインの未取得状態で、とりあえずサイトを公開しようとしています。<br /><a href=\"https://hogehoge.xsrv.jp/\" rel=\"nofollow ugc\">https://hogehoge.xsrv.jp/</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">公開後に、既存のドメインのサブドメインを付けることができるかもしれません。ドメイン管理者との調整に時間がかかりそうです。<br /><a href=\"https://sub-hogehoge.abc.or.jp/\" rel=\"nofollow ugc\">https://sub-hogehoge.abc.or.jp/</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">サブドメインを付けて、WordPress アドレスとサイトアドレスを <a href=\"https://sub-hogehoge.abc.or.jp/\" rel=\"nofollow ugc\">https://sub-hogehoge.abc.or.jp/</a> に変更すると、これまでの <a href=\"https://hogehoge.xsrv.jp/\" rel=\"nofollow ugc\">https://hogehoge.xsrv.jp/</a> へのアクセスは404エラーになりますか？　「WordPressの機能でリダイレクトするのでは」とも聞いたので、こちらでお尋ねします。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"masako2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694493\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: WordPressにログインできなくなった\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694493\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 25 Aug 2026 13:05:53 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:849:\"\n						\n						<p class=\"wp-block-paragraph\">ご報告ありがとうございます。<br />解決したとのことで、何よりです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">ユーザー名でログインできなかった原因までは特定できませんが、ブラウザーの自動入力やプラグインの一時的な状態なども考えられます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 本体・テーマ・プラグインを最新の状態にし、念のため、「ユーザー」一覧に心当たりのない管理者がいないことをご確認ください。</p>\n\n\n\n<p class=\"wp-block-paragraph\">今後もし同じ症状が再発した場合は、発生日時、入力したログイン名、表示されたエラーメッセージ、SiteGuard のログイン履歴をご確認くださいね。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"瀬戸内ことり (Setouchi Kotori)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694492\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: WordPressにログインできなくなった\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694492\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 25 Aug 2026 04:50:46 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:927:\"\n						\n						<p class=\"wp-block-paragraph\">瀬戸内さま、ありがとうございます。</p>\n\n\n\n<p class=\"wp-block-paragraph\">本日確認したところ、<code>invisible-recaptcha</code> フォルダーはWordpress管理画面から消えていました。<br />ファイルマネージャーから消した場合のWordpressの管理画面は、プラグインが無効になるのではなく消えるのですね、失礼いたしました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">昨日は、メールアドレスからのログインはできるけれど、ユーザー名からのログインはできず、不安定な状態でしたが、本日はMailとユーザ名ともに正常にログインができたので、完全に解決したのではないかと思います。</p>\n\n\n\n<p class=\"wp-block-paragraph\">色々と教えていただいて、本当にありがとうございました。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"shibuchi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694489\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: WordPressにログインできなくなった\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694489\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 24 Aug 2026 08:32:05 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:552:\"\n						\n						<p class=\"wp-block-paragraph\">無効化されていれば通常は動作しませんが、使用していないプラグインを残しておく必要はありません。</p>\n\n\n\n<p class=\"wp-block-paragraph\">今後、万が一、脆弱性が見つかった場合のリスクや更新管理の対象を減らすため、削除することをおすすめいたします。</p>\n\n\n\n<p class=\"wp-block-paragraph\">必要になった場合は、WordPress の管理画面から最新版を再度インストールできます。</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"瀬戸内ことり (Setouchi Kotori)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:182:\"https://ja.wordpress.org/support/topic/%e7%ae%a1%e7%90%86%e7%94%bb%e9%9d%a2%e3%81%ab%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e3%81%a7%e3%81%8d%e3%81%be%e3%81%9b%e3%82%93-3/#post-11694488\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"返信先: 管理画面にアクセスできません\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:182:\"https://ja.wordpress.org/support/topic/%e7%ae%a1%e7%90%86%e7%94%bb%e9%9d%a2%e3%81%ab%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e3%81%a7%e3%81%8d%e3%81%be%e3%81%9b%e3%82%93-3/#post-11694488\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 24 Aug 2026 08:28:42 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2186:\"\n						\n						<p class=\"wp-block-paragraph\">WordPress のバージョンをご確認いただきありがとうございます。<br />とても古いバージョンの WordPress をお使いだったのですね･･･。<br />先に伺えばよかったです。</p>\n\n\n\n<p class=\"wp-block-paragraph\">ご認識のとおり、WordPress 4.2.38 は PHP 7.4に対応していません。</p>\n\n\n\n<p class=\"wp-block-paragraph\">これ以上、本番環境を変更せず、まず全ファイルとデータベースをバックアップしてください。<br />また、確認後は <code>WP_DEBUG</code> を <code>false</code> に戻してください。</p>\n\n\n\n<p class=\"wp-block-paragraph\">アーカイブが目的であれば、ローカルなど外部へ公開しない場所に変更前と同じ WordPress 4.2.38・PHP 5.4 の環境を再現し、サイトを復元してから静的 HTML として保存する方法が安全です。</p>\n\n\n\n<p class=\"wp-block-paragraph\">この作業にはデータベースの移行や旧サーバー環境の構築が必要です。作業に不慣れな場合は、現在のバックアップを確保した上で、WordPress の復旧・移行に対応できる専門業者へ依頼されることをおすすめいたします。</p>\n\n\n<ul id=\"bbp-reply-revision-log-11694488\" class=\"bbp-reply-revision-log\">\n\n	<li id=\"bbp-reply-revision-log-11694488-item-11694490\" class=\"bbp-reply-revision-log-item\">\n		この返信は3日、 21時間前に<a href=\"https://ja.wordpress.org/support/users/setouchikotori/\" title=\"瀬戸内ことり (Setouchi Kotori) のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">瀬戸内ことり (Setouchi Kotori)</span></a>が編集しました。\n	</li>\n	<li id=\"bbp-reply-revision-log-11694488-item-11694491\" class=\"bbp-reply-revision-log-item\">\n		この返信は3日、 21時間前に<a href=\"https://ja.wordpress.org/support/users/setouchikotori/\" title=\"瀬戸内ことり (Setouchi Kotori) のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">瀬戸内ことり (Setouchi Kotori)</span></a>が編集しました。\n	</li>\n\n</ul>\n\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"瀬戸内ことり (Setouchi Kotori)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:182:\"https://ja.wordpress.org/support/topic/%e7%ae%a1%e7%90%86%e7%94%bb%e9%9d%a2%e3%81%ab%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e3%81%a7%e3%81%8d%e3%81%be%e3%81%9b%e3%82%93-3/#post-11694486\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"返信先: 管理画面にアクセスできません\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:182:\"https://ja.wordpress.org/support/topic/%e7%ae%a1%e7%90%86%e7%94%bb%e9%9d%a2%e3%81%ab%e3%82%a2%e3%82%af%e3%82%bb%e3%82%b9%e3%81%a7%e3%81%8d%e3%81%be%e3%81%9b%e3%82%93-3/#post-11694486\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 24 Aug 2026 07:40:38 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2922:\"\n						\n						<p class=\"wp-block-paragraph\">ご回答ありがとうございます。<br /><br />はい、「keni62_wp_corp」は「賢威 6.2 WordPressコーポレート版」です。<br /><br />ご助言いただいた方法を試してみました。<br /><br />FTPから&nbsp;<code>wp-content/plugins</code>を&nbsp;<code>plugins_old</code>&nbsp;に変更してプラグインを無効化しましたが、ログイン画面は白いままでした。<br /><br />その後、<code>themes</code>&nbsp;の名前を変更して確認しましたが、こちらでも改善しませんでした。<br /><br />また、<code>keni62_wp_corp</code>&nbsp;のフォルダ名を&nbsp;<code>keni62_wp_corp_old</code>に変更して確認したところ、今度は「HTTP ERROR 500」となりました。<br /><br />その後、<code>wp-config.php</code>&nbsp;の&nbsp;<code>WP_DEBUG</code>&nbsp;を true にして確認したところ、現在は以下のようなエラーが表示されています。<br /><br /><code>Fatal error: Uncaught Error: Cannot create references to/from string offsets</code><br /><br />エラー箇所は、<br /><br /><code>/wp/wp-includes/user.php</code>の54行目<br /><br />となっています。<br /><br />また、FTPで&nbsp;<code>wp-includes/version.php</code>&nbsp;を確認したところ、<br /><br /><code>$wp_version = \'4.2.38\';</code><br /><br />となっていました。<br /><br />PHPのバージョンを5.4から7.4へ変更した直後にログイン画面が真っ白になったため、現在はテーマだけではなく、古いWordPress本体とPHP 7.4との互換性も原因ではないかと考えています。<br /><br />なお、<code>wp-content/uploads</code>&nbsp;を確認したところ、2015年から2026年までの年別フォルダが残っており、画像ファイルも確認できました。<br /><br />今回の目的は、WordPressを最新の状態に戻して編集できるようにすることよりも、これまで公開していたサイトを、できればアーカイブとして閲覧できる状態に戻すことです。<br /><br />この場合、現在のWordPress 4.2.38やデータベース、画像などを壊さずに保存したうえで、アーカイブとして復旧するためには、どのような方法を取るのがよいでしょうか。<br /><br />ご助言いただけますと幸いです。</p>\n\n\n<ul id=\"bbp-reply-revision-log-11694486\" class=\"bbp-reply-revision-log\">\n\n	<li id=\"bbp-reply-revision-log-11694486-item-11694487\" class=\"bbp-reply-revision-log-item\">\n		この返信は3日、 21時間前に<a href=\"https://ja.wordpress.org/support/users/setouchikotori/\" title=\"瀬戸内ことり (Setouchi Kotori) のプロフィールを表示\" class=\"bbp-author-link\"><span  class=\"bbp-author-name\">瀬戸内ことり (Setouchi Kotori)</span></a>が編集しました。\n	</li>\n\n</ul>\n\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"cocoprico\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694485\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"返信先: WordPressにログインできなくなった\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:178:\"https://ja.wordpress.org/support/topic/wordpress%e3%81%ab%e3%83%ad%e3%82%b0%e3%82%a4%e3%83%b3%e3%81%a7%e3%81%8d%e3%81%aa%e3%81%8f%e3%81%aa%e3%81%a3%e3%81%9f/page/2/#post-11694485\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 24 Aug 2026 05:14:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:592:\"\n						\n						<p class=\"wp-block-paragraph\">ありがとうございます。<br /><code>invisible-recaptcha</code> フォルダーをファイルマネージャで削除して、Wordpressログアウト後にログインができました。</p>\n\n\n\n<p class=\"wp-block-paragraph\">昨日、再度ログインした際に、Invisible reCaptcha を管理画面から再インストールしているのですが、特に使っていないため、Invisible reCaptcha を無効にしたまま削除せずWordpressに残しておいても差し支えは無いでしょうか？</p>\n						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"shibuchi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:44:\"https://ja.wordpress.org/support/forums/feed\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Fri, 28 Aug 2026 05:56:16 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:4:\"vary\";s:37:\"Accept-Encoding, accept, content-type\";s:6:\"x-olaf\";s:3:\"⛄\";s:12:\"x-robots-tag\";s:15:\"noindex, follow\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:2:\"br\";s:7:\"alt-svc\";s:5:\"clear\";s:4:\"x-nc\";s:9:\"HIT dca 2\";}s:5:\"build\";i:1760643936;s:21:\"cache_expiration_time\";i:1787939776;s:23:\"__cache_expiration_time\";i:1787939776;}','off'),
